import React, { useState } from 'react';

export default function AdminDashboard() {
  // ข้อมูลจำลองคำขอยืมทั้งหมดที่รอแอดมินอนุมัติ
  const [requests, setRequests] = useState([
    {
      id: 1,
      studentName: "กฤษฎา คงแก้ว",
      studentId: "650710668",
      equipmentName: "Sony Mirrorless Camera Alpha 6400",
      quantity: 1,
      borrowDate: "2026-11-15",
      returnDate: "2026-11-18",
      purpose: "ถ่ายโปรเจกต์วิดีโอส่งอาจารย์",
      status: "รออนุมัติ"
    },
    {
      id: 2,
      studentName: "สมชาย ใจดี",
      studentId: "650710999",
      equipmentName: "Shure SM58 Vocal Microphone",
      quantity: 2,
      borrowDate: "2026-11-12",
      returnDate: "2026-11-14",
      purpose: "จัดกิจกรรมดนตรีในคณะ",
      status: "รออนุมัติ"
    }
  ]);

  // ฟังก์ชันกดอนุมัติ
  const handleApprove = (id) => {
    setRequests(requests.map(item => 
      item.id === id ? { ...item, status: 'กำลังใช้งาน' } : item
    ));
  };

  // ฟังก์ชันกดปฏิเสธ
  const handleReject = (id) => {
    setRequests(requests.map(item => 
      item.id === id ? { ...item, status: 'ไม่อนุมัติ' } : item
    ));
  };

  return (
    <div style={{ maxWidth: '1000px', margin: '30px auto', padding: '0 20px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
        <div>
          <h2 style={{ color: '#1E293B', marginBottom: '6px', fontSize: '22px' }}>🛡️ หน้าจัดการหลังบ้าน (Admin Dashboard)</h2>
          <p style={{ color: '#64748B', fontSize: '14px', margin: 0 }}>ตรวจสอบและอนุมัติคำขอยืมอุปกรณ์จากนักศึกษา</p>
        </div>
      </div>

      {requests.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '40px', background: '#FFFFFF', borderRadius: '12px', border: '1px solid #E2E8F0', color: '#64748B' }}>
          ไม่มีคำขอยืมที่รอการตรวจสอบ
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          {requests.map((item) => (
            <div key={item.id} style={{
              background: '#FFFFFF',
              padding: '20px',
              borderRadius: '12px',
              border: '1px solid #E2E8F0',
              boxShadow: '0 2px 10px rgba(0,0,0,0.02)',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
              flexWrap: 'wrap',
              gap: '16px'
            }}>
              <div style={{ flex: 1, minWidth: '300px' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '6px' }}>
                  <h4 style={{ margin: 0, color: '#1E293B', fontSize: '16px' }}>{item.equipmentName}</h4>
                  <span style={{
                    background: item.status === 'รออนุมัติ' ? '#FEF3C7' : item.status === 'กำลังใช้งาน' ? '#DBEAFE' : '#FEE2E2',
                    color: item.status === 'รออนุมัติ' ? '#D97706' : item.status === 'กำลังใช้งาน' ? '#1D4ED8' : '#DC2626',
                    padding: '4px 10px',
                    borderRadius: '20px',
                    fontSize: '12px',
                    fontWeight: '600'
                  }}>
                    {item.status}
                  </span>
                </div>
                <p style={{ margin: '0 0 4px 0', fontSize: '13px', color: '#475569' }}>
                  🧑‍🎓 <strong>ผู้ยืม:</strong> {item.studentName} (รหัส: {item.studentId}) | 📌 <strong>จำนวน:</strong> {item.quantity} ชิ้น
                </p>
                <p style={{ margin: '0 0 4px 0', fontSize: '13px', color: '#475569' }}>
                  📅 <strong>วันที่ยืม - คืน:</strong> {item.borrowDate} ถึง {item.returnDate}
                </p>
                <p style={{ margin: 0, fontSize: '13px', color: '#64748B' }}>
                  💬 <strong>วัตถุประสงค์:</strong> {item.purpose}
                </p>
              </div>

              {item.status === 'รออนุมัติ' && (
                <div style={{ display: 'flex', gap: '8px' }}>
                  <button 
                    onClick={() => handleApprove(item.id)}
                    style={{
                      padding: '8px 16px',
                      background: '#16A34A',
                      color: '#FFFFFF',
                      border: 'none',
                      borderRadius: '6px',
                      fontSize: '13px',
                      fontWeight: '600',
                      cursor: 'pointer'
                    }}
                  >
                    อนุมัติ
                  </button>
                  <button 
                    onClick={() => handleReject(item.id)}
                    style={{
                      padding: '8px 16px',
                      background: '#DC2626',
                      color: '#FFFFFF',
                      border: 'none',
                      borderRadius: '6px',
                      fontSize: '13px',
                      fontWeight: '600',
                      cursor: 'pointer'
                    }}
                  >
                    ปฏิเสธ
                  </button>
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
